const applyPluginProperties = ({
  error,
  plugin,
  plugin: { properties, fullName },
  plugins,
}) => {
  if (properties === undefined) {
    return
  }

  const info = getErrorPluginInfo({ error, plugins, plugin })
  const newProps = properties(info)

  if (!isPlainObj(newProps)) {
    throw new TypeError(
      `Plugin "${fullName}"'s "properties()" must return a plain object: ${newProps}`,
    )
  }

  assignError(error, newProps, plugins)
}

const addInstanceMethod = (
  { plugin, plugins, ErrorClass },
  [methodName, methodFunc],
) => {
  setNonEnumProp(
    ErrorClass.prototype,
    methodName,
    function boundInstanceMethod(...args) {
      return callInstanceMethod({
        // eslint-disable-next-line fp/no-this, no-invalid-this
        error: this,
        methodFunc,
        methodName,
        plugin,
        plugins,
        ErrorClass,
