const callStaticMethod = (
  { methodFunc, plugin, plugins, ErrorClass },
  ...args
) => {
  const { classOpts } = classesData.get(ErrorClass)
  const { args: argsA, methodOpts } = getMethodOpts(args, plugin)
  const options = finalizePluginsOpts({
    pluginsOpts: classOpts,
    methodOpts,
    plugins,
    plugin,
  })
  const info = getPluginInfo({
    options,
    ErrorClass,
    methodOpts,
    plugins,
    plugin,
  })
  return methodFunc(info, ...argsA)
}

const validatePluginName = (plugin) => {
  if (plugin.name === undefined) {
    throw new TypeError(`The plugin is missing a "name": ${plugin}`)
  }

  const { name } = plugin

  if (typeof name !== 'string') {
    throw new TypeError(`The plugin "name" must be a string: ${name}`)
  }

  validateNameString(name)

  return { ...plugin, fullName: `${NAME_PREFIX}${name}` }
}

const validateEachPlugin = ({
  pluginA,
  pluginB,
  indexA,
  indexB,
  ParentError,
}) => {
  if (indexA === indexB) {
    return
  }

  if (pluginA.name === pluginB.name) {
    throw new TypeError(
      `The "plugins" option of "${ParentError.name}.subclass()" must not include "${pluginA.fullName}": this plugin has already been included.`,
    )
  }

  const duplicateName = findDuplicateKey(
    { ...pluginA.instanceMethods, ...pluginA.staticMethods },
    { ...pluginB.instanceMethods, ...pluginB.staticMethods },
  )

  if (duplicateName !== undefined) {
    throw new TypeError(
      `The plugins "${pluginA.fullName}" and "${pluginB.fullName}" must not both define the same "${duplicateName}()" method.`,
    )
  }
}

const callMethod = ({ methodFunc, plugin, plugins, error, args }) => {
  const { args: argsA, methodOpts } = getMethodOpts(args, plugin)
  const info = getErrorPluginInfo({ error, methodOpts, plugins, plugin })
  return methodFunc(info, ...argsA)
}

const callInstanceMethod = ({
  error,
  methodFunc,
  methodName,
  plugin,
  plugins,
  ErrorClass,
  args,
}) => {
  if (!(error instanceof ErrorClass)) {
    throw new TypeError(
      `Missing "this" context: "${methodName}()" must be called using "error.${methodName}()"`,
    )
  }

  return callMethod({ methodFunc, plugin, plugins, error, args })
}

const normalizeClassOpts = (ParentError, classOpts = {}) => {
  if (!isPlainObj(classOpts)) {
    throw new TypeError(
      `The second argument of "${ParentError.name}.subclass()" must be a plain object, not: ${classOpts}`,
    )
  }

  return classOpts
}

const shouldPrefixCause = (error, ErrorClass) => {
  const { cause } = error
  return (
    hasValidName(cause) &&
    (hasUsefulName(cause, ErrorClass) || cause.name !== cause.constructor.name)
  )
}

const prefixCause = (cause) => {
  const oldMessage = typeof cause.message === 'string' ? cause.message : ''
  const newMessage =
    oldMessage === '' ? cause.name : `${cause.name}: ${oldMessage}`
  setErrorMessage(cause, newMessage)
  return oldMessage
}

const finalizePluginsOpts = ({
  pluginsOpts,
  methodOpts,
  plugins,
  plugin,
}) => {
  const pluginsOptsA = mergeMethodOpts(pluginsOpts, methodOpts, plugins)
  const pluginsOptsB = deepClone(pluginsOptsA)
  const options = getPluginOpts({
    pluginsOpts: pluginsOptsB,
    plugin,
    full: true,
  })
  return options
}

const mergeSpecificCause = (error, cause) => {
  error.cause = cause
  error.wrap = true
  return mergeErrorCause(error)
}

const mergePrefixedError = (error) => {
  const { cause } = error
  const oldMessage = prefixCause(cause)
  const errorA = mergeErrorCause(error)

  if (cause !== errorA) {
    undoPrefixCause(cause, oldMessage)
  }

  return errorA
}

const mergeCause = (error, ErrorClass) => {
  if (!isErrorInstance(error.cause)) {
    return mergeErrorCause(error)
  }

  error.wrap = isSubclass(error.cause.constructor, ErrorClass)

  if (!shouldPrefixCause(error, ErrorClass)) {
    return mergeErrorCause(error)
  }

  return mergePrefixedError(error)
}

const assignError = (
  error,
  { message, stack, ...newProps },
  plugins,
) => {
  if (stack !== undefined) {
    setErrorStack(error, stack)
  }

  if (message !== undefined) {
    setErrorMessage(error, message)
  }

  if (Reflect.ownKeys(newProps).length === 0) {
    return
  }

  const keys = excludeKeys(newProps, [
    ...OMITTED_PROPS,
    ...getPluginsMethodNames(plugins),
  ])
  setErrorProps(error, keys)
}

const mergePluginOpts = (oldOpts, newOpts, name) => {
  const pluginOpt = mergeOpt(oldOpts[name], newOpts[name])
  return pluginOpt === undefined ? undefined : [name, pluginOpt]
}

const mergeOpt = (oldOpt, newOpt) => {
  if (newOpt === undefined) {
    return oldOpt
  }

  if (isPlainObj(oldOpt) && isPlainObj(newOpt)) {
    return { ...oldOpt, ...newOpt }
  }

  return newOpt
}

const deepCloneObject = (object) => {
  const copy = {}

  // eslint-disable-next-line fp/no-loops
  for (const key of Reflect.ownKeys(object)) {
    const descriptor = Object.getOwnPropertyDescriptor(object, key)
    const childCopy = deepClone(descriptor.value)
    // eslint-disable-next-line fp/no-mutating-methods
    Object.defineProperty(copy, key, { ...descriptor, value: childCopy })
  }

  return copy
}

const deepClone = (value) => {
  if (Array.isArray(value)) {
    return value.map(deepClone)
  }

  if (isPlainObj(value)) {
    return deepCloneObject(value)
  }

  return value
}

const normalizeAllMethods = (plugin) => {
  const pluginA = normalizeMethods({
    ...INSTANCE_METHODS,
    plugin,
    propName: 'instanceMethods',
  })
  const pluginB = normalizeMethods({
    ...STATIC_METHODS,
    plugin: pluginA,
    propName: 'instanceMethods',
  })
  const pluginC = normalizeMethods({
    ...STATIC_METHODS,
    plugin: pluginB,
    propName: 'staticMethods',
  })
  return pluginC
}

const normalizeMethods = ({
  plugin,
  propName,
  coreObject,
  coreObjectName,
  forbiddenNames,
}) => {
  const methods = plugin[propName] ?? {}

  if (!isPlainObj(methods)) {
    throw new TypeError(
      `The plugin "${plugin.fullName}"'s "${propName}" property must be either undefined or a plain object, not: ${methods}`,
    )
  }

  Object.entries(methods).forEach(([methodName, methodValue]) => {
    validateMethod({
      methodValue,
      propName,
      methodName,
      plugin,
      coreObject,
      coreObjectName,
      forbiddenNames,
    })
  })
  return { ...plugin, [propName]: methods }
}

const validateSubclass = (ErrorClass) => {
  if (classesData.has(ErrorClass)) {
    return
  }

  const { name } = ErrorClass
  const { name: parentName } = Object.getPrototypeOf(ErrorClass)
  throw new Error(
    `"new ${name}()" must not be directly called.
This error class should be created like this instead:
  export const ${name} = ${parentName}.subclass('${name}')`,
  )
}

const lastArgIsOptions = ({ isOptions, fullName }, lastArg) => {
  const isOptionsResult = isOptions(lastArg)

  if (typeof isOptionsResult !== 'boolean') {
    throw new TypeError(
      `The plugin "${fullName}"'s "isOptions()" method must return a boolean, not: ${typeof isOptionsResult}`,
    )
  }

  return isOptionsResult
}

const normalizePluginsOpt = (ParentError, plugins = []) => {
  if (!Array.isArray(plugins)) {
    throw new TypeError(
      `The "plugins" option of "${ParentError.name}.subclass()" must be an array: ${plugins}`,
    )
  }

  return plugins
}

const normalizePlugin = (plugin, ParentError) => {
  if (!isPlainObj(plugin)) {
    throw new TypeError(
      `The "plugins" option of "${ParentError.name}.subclass()" must be an array of plugin objects: ${plugin}`,
    )
  }

  const pluginA = validatePluginName(plugin)
  validateOptionalFuncs(pluginA)
  const pluginB = normalizeAllMethods(pluginA)
  validateSameMethods(pluginB)
  const pluginC = normalizeIsOptions({ plugin: pluginB })
  const pluginD = normalizeGetOptions({ plugin: pluginC })
  return pluginD
}
